What is the output of the following code?
Code:
class BankAccount:
    def __init__(self, balance):
        self._balance = balance
    def withdraw(self, amt):
        if amt > self._balance:
            raise ValueError("Insufficient funds")
        self._balance -= amt

acc = BankAccount(100)
acc.withdraw(150)

